use crate::ciphers::salsa_lite::cipher::salsa_lite_encrypt;
use crate::ciphers::salsa_lite::keys::salsa_lite_default_key;
use crate::core::sample::sample_bytes;
use crate::core::timer::Stopwatch;

/// Time one encryption pass over `input_len` generated bytes.
pub fn salsa_lite_measure(input_len: usize) -> u128 {
    let data = sample_bytes(input_len);
    let key = salsa_lite_default_key();
    let watch = Stopwatch::start();
    let sealed = salsa_lite_encrypt(&data, key);
    std::hint::black_box(sealed.len());
    watch.elapsed_ns()
}
